import presetData from "./gradient-background-presets.json";

export const GRADIENT_BACKGROUND_SCHEMA_VERSION = 3 as const;
/**
 * Schema 1 named the structural noise controls `noiseOctaves`/`noiseFrequency`;
 * schema 2 freed those names for the surface noise and renamed the structural
 * pair to `field*`. Schema 3 generalized the ribbon-only `ribbonDensity` into
 * `patternDensity` once the field stopped being ribbons alone.
 */
const GRADIENT_BACKGROUND_LEGACY_SCHEMA_VERSIONS = [1, 2] as const;
export const GRADIENT_BACKGROUND_QUALITY_VALUES = [
  "auto",
  "low",
  "medium",
  "high",
] as const;
export const GRADIENT_BACKGROUND_COLOR_MODES = ["custom", "palette"] as const;
export const GRADIENT_BACKGROUND_PATTERNS = [
  "ribbon",
  "radial",
  "conic",
  "blobs",
  "contour",
  "cellular",
] as const;
export const GRADIENT_BACKGROUND_EFFECTS = [
  "none",
  "ascii",
  "halftone",
  "dots",
  "lines",
  "dither",
  "crosshatch",
] as const;
export const GRADIENT_BACKGROUND_EFFECT_COLOR_MODES = [
  "gradient",
  "duotone",
  "ink",
] as const;
export const GRADIENT_BACKGROUND_EFFECT_SHAPES = [
  "round",
  "square",
  "cross",
] as const;

export type GradientBackgroundPresetName = keyof typeof presetData;
export type GradientBackgroundQuality =
  (typeof GRADIENT_BACKGROUND_QUALITY_VALUES)[number];
export type GradientBackgroundColorMode =
  (typeof GRADIENT_BACKGROUND_COLOR_MODES)[number];
export type GradientBackgroundPattern =
  (typeof GRADIENT_BACKGROUND_PATTERNS)[number];
export type GradientBackgroundEffect =
  (typeof GRADIENT_BACKGROUND_EFFECTS)[number];
export type GradientBackgroundEffectColorMode =
  (typeof GRADIENT_BACKGROUND_EFFECT_COLOR_MODES)[number];
export type GradientBackgroundEffectShape =
  (typeof GRADIENT_BACKGROUND_EFFECT_SHAPES)[number];

export interface BalsaBackgroundConfig {
  schemaVersion: typeof GRADIENT_BACKGROUND_SCHEMA_VERSION;
  preset: GradientBackgroundPresetName;
  seed: number;
  colorMode: GradientBackgroundColorMode;
  colors: string[];
  speed: number;
  scale: number;
  warp: number;
  wave: number;
  softness: number;
  grain: number;
  grainSize: number;
  contrast: number;
  brightness: number;
  direction: number;
  quality: GradientBackgroundQuality;
  fieldOctaves: number;
  fieldFrequency: number;
  noiseAmount: number;
  noiseOctaves: number;
  noiseFrequency: number;
  warpFrequency: number;
  /** Which field generator draws the gradient. */
  pattern: GradientBackgroundPattern;
  /**
   * How often the pattern repeats: ribbon count, concentric ring count, conic
   * arm count, or contour band count depending on `pattern`. Ignored by
   * `blobs` and `cellular`, which are sized by `patternComplexity`.
   */
  patternDensity: number;
  patternCenterX: number;
  patternCenterY: number;
  /** Blob count for `blobs`, cell density for `cellular`. */
  patternComplexity: number;
  /** Post-effect applied to the rendered gradient. */
  effect: GradientBackgroundEffect;
  /** Effect cell size in CSS pixels, so density survives DPR and PNG capture. */
  effectScale: number;
  effectAngle: number;
  /** Blend between the raw gradient (0) and the fully applied effect (1). */
  effectMix: number;
  effectColorMode: GradientBackgroundEffectColorMode;
  effectInk: string;
  effectPaper: string;
  effectInvert: boolean;
  effectLevels: number;
  effectShape: GradientBackgroundEffectShape;
  effectCharacters: string;
}

export type GradientBackgroundConfigInput = Partial<
  Omit<BalsaBackgroundConfig, "schemaVersion" | "colors">
> & {
  schemaVersion?: number;
  colors?: readonly string[];
};

export interface GradientBackgroundDirectOverrides
  extends Partial<
    Omit<BalsaBackgroundConfig, "schemaVersion" | "preset" | "colors">
  > {
  colors?: readonly string[];
}

export interface GradientBackgroundCaptureOptions {
  width?: number;
  height?: number;
}

export interface GradientBackgroundExposed {
  capturePng: (options?: GradientBackgroundCaptureOptions) => Promise<Blob>;
  renderStill: () => void;
}

export const gradientBackgroundPresetNames = Object.freeze(
  Object.keys(presetData) as GradientBackgroundPresetName[],
);

const HEX_COLOR = /^#[\da-f]{6}$/i;
const DEFAULT_PRESET: GradientBackgroundPresetName = "obsidian-fold";

/**
 * Fallbacks for fields a preset may not carry. Presets written before schema 3
 * have no pattern or effect keys at all, and a config handed in by an agent or
 * an older export is free to omit any of them.
 */
export const GRADIENT_BACKGROUND_DEFAULTS = Object.freeze({
  pattern: "ribbon" as GradientBackgroundPattern,
  patternDensity: 2.35,
  patternCenterX: 0,
  patternCenterY: 0,
  patternComplexity: 4,
  effect: "none" as GradientBackgroundEffect,
  effectScale: 10,
  effectAngle: 0,
  effectMix: 1,
  effectColorMode: "gradient" as GradientBackgroundEffectColorMode,
  effectInk: "#F5F5F4",
  effectPaper: "#0A0A0B",
  effectInvert: false,
  effectLevels: 4,
  effectShape: "round" as GradientBackgroundEffectShape,
  effectCharacters: " .:-=+*#%@",
});

export const gradientBackgroundRanges = Object.freeze({
  seed: { min: 0, max: 2147483647, step: 1 },
  speed: { min: 0, max: 2, step: 0.005 },
  scale: { min: 0.25, max: 4, step: 0.01 },
  warp: { min: 0, max: 2, step: 0.01 },
  wave: { min: 0, max: 2, step: 0.01 },
  softness: { min: 0.05, max: 1, step: 0.01 },
  grain: { min: 0, max: 0.5, step: 0.005 },
  grainSize: { min: 0.25, max: 4, step: 0.05 },
  contrast: { min: 0.5, max: 2, step: 0.01 },
  brightness: { min: -0.5, max: 0.5, step: 0.01 },
  direction: { min: -180, max: 180, step: 1 },
  fieldOctaves: { min: 1, max: 4, step: 1 },
  fieldFrequency: { min: 0.2, max: 4, step: 0.01 },
  noiseAmount: { min: 0, max: 0.5, step: 0.005 },
  noiseOctaves: { min: 1, max: 6, step: 1 },
  noiseFrequency: { min: 0.2, max: 4, step: 0.01 },
  warpFrequency: { min: 0.2, max: 4, step: 0.01 },
  patternDensity: { min: 0.5, max: 8, step: 0.05 },
  patternCenterX: { min: -1, max: 1, step: 0.01 },
  patternCenterY: { min: -1, max: 1, step: 0.01 },
  patternComplexity: { min: 1, max: 8, step: 1 },
  effectScale: { min: 2, max: 48, step: 0.5 },
  effectAngle: { min: -180, max: 180, step: 1 },
  effectMix: { min: 0, max: 1, step: 0.01 },
  effectLevels: { min: 2, max: 8, step: 1 },
  captureWidth: { min: 320, max: 4096, step: 1 },
  captureHeight: { min: 320, max: 4096, step: 1 },
} as const);

/** The longest character set the ASCII glyph atlas will build a column for. */
export const GRADIENT_BACKGROUND_MAXIMUM_CHARACTERS = 64;

function isLegacyGradientBackgroundSchemaVersion(value: unknown): boolean {
  return GRADIENT_BACKGROUND_LEGACY_SCHEMA_VERSIONS.includes(
    value as (typeof GRADIENT_BACKGROUND_LEGACY_SCHEMA_VERSIONS)[number],
  );
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function finiteNumber(value: unknown, fallback: number): number {
  return typeof value === "number" && Number.isFinite(value) ? value : fallback;
}

function clamp(value: unknown, fallback: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, finiteNumber(value, fallback)));
}

function clampInteger(
  value: unknown,
  fallback: number,
  min: number,
  max: number,
): number {
  return Math.round(clamp(value, fallback, min, max));
}

function normalizedColor(value: unknown, fallback: string): string {
  return typeof value === "string" && HEX_COLOR.test(value)
    ? value.toUpperCase()
    : fallback.toUpperCase();
}

function normalizedBoolean(value: unknown, fallback: boolean): boolean {
  return typeof value === "boolean" ? value : fallback;
}

/**
 * Control characters cannot be drawn into the glyph atlas and would silently
 * become blank columns, so they are dropped rather than rejected -- a config
 * with one stray character still renders. Anything printable is allowed
 * through, including non-Latin sets, and codepoints are counted rather than
 * UTF-16 units so a surrogate pair stays one glyph.
 */
function normalizedCharacters(value: unknown, fallback: string): string {
  if (typeof value !== "string") return fallback;
  const characters = Array.from(value).filter((character) => {
    const code = character.codePointAt(0) ?? 0;
    return code >= 0x20 && code !== 0x7f;
  });
  if (characters.length < 2) return fallback;
  return characters.slice(0, GRADIENT_BACKGROUND_MAXIMUM_CHARACTERS).join("");
}

function normalizedColors(value: unknown, fallback: readonly string[]): string[] {
  if (!Array.isArray(value)) return [...fallback];
  const bounded = value.slice(0, 6);
  if (bounded.length < 2) return [...fallback];
  return bounded.map((color, index) =>
    normalizedColor(color, fallback[index % fallback.length] ?? "#000000"),
  );
}

export function isGradientBackgroundPresetName(
  value: unknown,
): value is GradientBackgroundPresetName {
  return typeof value === "string" && value in presetData;
}

export function isGradientBackgroundQuality(
  value: unknown,
): value is GradientBackgroundQuality {
  return GRADIENT_BACKGROUND_QUALITY_VALUES.includes(
    value as GradientBackgroundQuality,
  );
}

export function isGradientBackgroundColorMode(
  value: unknown,
): value is GradientBackgroundColorMode {
  return GRADIENT_BACKGROUND_COLOR_MODES.includes(
    value as GradientBackgroundColorMode,
  );
}

export function isGradientBackgroundPattern(
  value: unknown,
): value is GradientBackgroundPattern {
  return GRADIENT_BACKGROUND_PATTERNS.includes(value as GradientBackgroundPattern);
}

export function isGradientBackgroundEffect(
  value: unknown,
): value is GradientBackgroundEffect {
  return GRADIENT_BACKGROUND_EFFECTS.includes(value as GradientBackgroundEffect);
}

export function isGradientBackgroundEffectColorMode(
  value: unknown,
): value is GradientBackgroundEffectColorMode {
  return GRADIENT_BACKGROUND_EFFECT_COLOR_MODES.includes(
    value as GradientBackgroundEffectColorMode,
  );
}

export function isGradientBackgroundEffectShape(
  value: unknown,
): value is GradientBackgroundEffectShape {
  return GRADIENT_BACKGROUND_EFFECT_SHAPES.includes(
    value as GradientBackgroundEffectShape,
  );
}

export function getGradientBackgroundPreset(
  name: GradientBackgroundPresetName,
): BalsaBackgroundConfig {
  return normalizeGradientBackgroundConfig(presetData[name]);
}

export function normalizeGradientBackgroundConfig(
  value: unknown,
  fallbackPreset: GradientBackgroundPresetName = DEFAULT_PRESET,
): BalsaBackgroundConfig {
  const input = isRecord(value) ? value : {};
  const preset = isGradientBackgroundPresetName(input.preset)
    ? input.preset
    : fallbackPreset;
  const fallback = { ...GRADIENT_BACKGROUND_DEFAULTS, ...presetData[preset] };
  const legacy = input.schemaVersion === 1;
  // Schema 3 renamed the key rather than changing its meaning, so an older
  // config's value is read straight across instead of being migrated away.
  const patternDensity = input.patternDensity ?? input.ribbonDensity;

  return {
    schemaVersion: GRADIENT_BACKGROUND_SCHEMA_VERSION,
    preset,
    seed: clampInteger(
      input.seed,
      fallback.seed,
      gradientBackgroundRanges.seed.min,
      gradientBackgroundRanges.seed.max,
    ),
    colorMode: isGradientBackgroundColorMode(input.colorMode)
      ? input.colorMode
      : (fallback.colorMode as GradientBackgroundColorMode),
    colors: normalizedColors(input.colors, fallback.colors),
    speed: clamp(input.speed, fallback.speed, 0, 2),
    scale: clamp(input.scale, fallback.scale, 0.25, 4),
    warp: clamp(input.warp, fallback.warp, 0, 2),
    wave: clamp(input.wave, fallback.wave, 0, 2),
    softness: clamp(input.softness, fallback.softness, 0.05, 1),
    grain: clamp(input.grain, fallback.grain, 0, 0.5),
    grainSize: clamp(input.grainSize, fallback.grainSize, 0.25, 4),
    contrast: clamp(input.contrast, fallback.contrast, 0.5, 2),
    brightness: clamp(input.brightness, fallback.brightness, -0.5, 0.5),
    direction: clamp(input.direction, fallback.direction, -180, 180),
    quality: isGradientBackgroundQuality(input.quality)
      ? input.quality
      : (fallback.quality as GradientBackgroundQuality),
    fieldOctaves: clampInteger(
      legacy ? input.noiseOctaves : input.fieldOctaves,
      fallback.fieldOctaves,
      1,
      4,
    ),
    fieldFrequency: clamp(
      legacy ? input.noiseFrequency : input.fieldFrequency,
      fallback.fieldFrequency,
      0.2,
      4,
    ),
    noiseAmount: clamp(input.noiseAmount, fallback.noiseAmount, 0, 0.5),
    noiseOctaves: clampInteger(
      legacy ? undefined : input.noiseOctaves,
      fallback.noiseOctaves,
      1,
      6,
    ),
    noiseFrequency: clamp(
      legacy ? undefined : input.noiseFrequency,
      fallback.noiseFrequency,
      0.2,
      4,
    ),
    warpFrequency: clamp(input.warpFrequency, fallback.warpFrequency, 0.2, 4),
    pattern: isGradientBackgroundPattern(input.pattern)
      ? input.pattern
      : (fallback.pattern as GradientBackgroundPattern),
    patternDensity: clamp(patternDensity, fallback.patternDensity, 0.5, 8),
    patternCenterX: clamp(input.patternCenterX, fallback.patternCenterX, -1, 1),
    patternCenterY: clamp(input.patternCenterY, fallback.patternCenterY, -1, 1),
    patternComplexity: clampInteger(
      input.patternComplexity,
      fallback.patternComplexity,
      1,
      8,
    ),
    effect: isGradientBackgroundEffect(input.effect)
      ? input.effect
      : (fallback.effect as GradientBackgroundEffect),
    effectScale: clamp(input.effectScale, fallback.effectScale, 2, 48),
    effectAngle: clamp(input.effectAngle, fallback.effectAngle, -180, 180),
    effectMix: clamp(input.effectMix, fallback.effectMix, 0, 1),
    effectColorMode: isGradientBackgroundEffectColorMode(input.effectColorMode)
      ? input.effectColorMode
      : (fallback.effectColorMode as GradientBackgroundEffectColorMode),
    effectInk: normalizedColor(input.effectInk, fallback.effectInk),
    effectPaper: normalizedColor(input.effectPaper, fallback.effectPaper),
    effectInvert: normalizedBoolean(input.effectInvert, fallback.effectInvert),
    effectLevels: clampInteger(input.effectLevels, fallback.effectLevels, 2, 8),
    effectShape: isGradientBackgroundEffectShape(input.effectShape)
      ? input.effectShape
      : (fallback.effectShape as GradientBackgroundEffectShape),
    effectCharacters: normalizedCharacters(
      input.effectCharacters,
      fallback.effectCharacters,
    ),
  };
}

/**
 * Shared controls do not mean the same thing to every generator: a
 * `patternDensity` of 2.35 is a handsome ribbon count but a dizzying number of
 * concentric rings, and `wave` reads as ridge strength for ribbons and as ring
 * strength for radial. These are the values a pattern wants when the user
 * switches to it, applied by the studio rather than by `normalize` -- rewriting
 * an authored config on every parse would make saved backgrounds unstable.
 */
export const gradientBackgroundPatternDefaults: Readonly<
  Record<GradientBackgroundPattern, Partial<BalsaBackgroundConfig>>
> = Object.freeze({
  ribbon: { patternDensity: 2.35, wave: 1.2, warp: 1.12, softness: 0.7 },
  radial: { patternDensity: 1.4, wave: 0.85, warp: 0.9, softness: 0.8 },
  conic: { patternDensity: 2, wave: 1, warp: 1.25, softness: 0.75 },
  blobs: { patternComplexity: 5, wave: 1.1, warp: 0.7, softness: 0.9, scale: 0.85 },
  contour: { patternDensity: 3.2, wave: 1.35, warp: 1.05, softness: 0.45 },
  cellular: { patternComplexity: 4, wave: 1.15, warp: 0.85, softness: 0.6 },
});

export function applyGradientBackgroundPatternDefaults(
  config: BalsaBackgroundConfig,
  pattern: GradientBackgroundPattern,
): BalsaBackgroundConfig {
  return normalizeGradientBackgroundConfig({
    ...config,
    ...gradientBackgroundPatternDefaults[pattern],
    pattern,
  }, config.preset);
}

export function resolveGradientBackgroundConfig(options: {
  preset?: GradientBackgroundPresetName;
  config?: GradientBackgroundConfigInput;
  overrides?: GradientBackgroundDirectOverrides;
} = {}): BalsaBackgroundConfig {
  const selectedPreset = options.preset
    ?? (isGradientBackgroundPresetName(options.config?.preset)
      ? options.config.preset
      : DEFAULT_PRESET);
  const base = presetData[selectedPreset];
  // A legacy config is normalized first so its renamed keys land under their
  // current names before the spread below merges it over the preset -- spreading
  // it raw would leave `noiseOctaves` meaning two different things at once.
  const config = isLegacyGradientBackgroundSchemaVersion(options.config?.schemaVersion)
    ? normalizeGradientBackgroundConfig(options.config, selectedPreset)
    : options.config;
  return normalizeGradientBackgroundConfig({
    ...base,
    ...config,
    ...options.overrides,
    preset: selectedPreset,
    schemaVersion: GRADIENT_BACKGROUND_SCHEMA_VERSION,
  }, selectedPreset);
}

export function parseGradientBackgroundConfig(
  value: string | unknown,
): BalsaBackgroundConfig {
  const parsed: unknown = typeof value === "string" ? JSON.parse(value) : value;
  if (!isRecord(parsed)) throw new Error("Background configuration must be an object.");
  if (
    parsed.schemaVersion !== GRADIENT_BACKGROUND_SCHEMA_VERSION
    && !isLegacyGradientBackgroundSchemaVersion(parsed.schemaVersion)
  ) {
    throw new Error(
      `Unsupported Balsa background schema version: ${String(parsed.schemaVersion)}.`,
    );
  }
  if (!isGradientBackgroundPresetName(parsed.preset)) {
    throw new Error(`Unknown Balsa background preset: ${String(parsed.preset)}.`);
  }
  if (!Array.isArray(parsed.colors) || parsed.colors.length < 2 || parsed.colors.length > 6) {
    throw new Error("A Balsa background configuration requires two to six colors.");
  }
  if (parsed.colors.some((color) => typeof color !== "string" || !HEX_COLOR.test(color))) {
    throw new Error("Background colors must use six-digit hexadecimal values.");
  }
  return normalizeGradientBackgroundConfig(parsed, parsed.preset);
}

export function serializeGradientBackgroundConfig(
  value: unknown,
): string {
  return `${JSON.stringify(normalizeGradientBackgroundConfig(value), null, 2)}\n`;
}

export function randomGradientBackgroundSeed(
  random: () => number = Math.random,
): number {
  return Math.floor(Math.min(0.999999999, Math.max(0, random())) * 2147483648);
}

/**
 * All six tonal roles, the shader's maximum. `muted` anchors the neutral end so
 * a light palette's saturated accents read as tint rather than a dark mass, and
 * keeping all three accents preserves the mid-tones that give a dark palette its
 * depth -- dropping one leaves those fields collapsing toward flat black.
 */
const paletteRoles = [
  "--balsa-color-background",
  "--balsa-color-surface",
  "--balsa-color-muted",
  "--balsa-color-primary",
  "--balsa-color-secondary",
  "--balsa-color-accent",
] as const;

const paletteBackgroundRole = "--balsa-color-background";
/**
 * Overlaid text is rarely the full-strength foreground -- ledes and eyebrows use
 * dimmer roles. Holding the floor against the dimmest of them keeps the ones
 * above it readable too.
 */
const paletteTextRoles = [
  "--balsa-color-muted-foreground",
  "--balsa-color-foreground",
] as const;

/** WCAG AA for body text: the floor the palette's own -foreground tokens use. */
export const GRADIENT_BACKGROUND_MINIMUM_CONTRAST = 4.5;

interface RgbColor {
  red: number;
  green: number;
  blue: number;
}

/**
 * Hex and rgb() only. Palettes emit hex, but a project may override a role with
 * a color this cannot read -- those stops are left untouched rather than
 * guessed at, so an unparseable value degrades to today's behavior.
 */
function parseColor(value: string): RgbColor | undefined {
  const input = value.trim();
  const hex = input.startsWith("#") ? input.slice(1) : undefined;
  if (hex && (hex.length === 3 || hex.length === 6)) {
    const width = hex.length / 3;
    const channel = (index: number): number => {
      const part = hex.slice(index * width, index * width + width);
      const parsed = Number.parseInt(width === 1 ? part + part : part, 16);
      return Number.isNaN(parsed) ? Number.NaN : parsed;
    };
    const color = { red: channel(0), green: channel(1), blue: channel(2) };
    return Number.isNaN(color.red + color.green + color.blue) ? undefined : color;
  }
  const rgb = /^rgba?\(\s*([\d.]+)[\s,]+([\d.]+)[\s,]+([\d.]+)/i.exec(input);
  if (!rgb) return undefined;
  return {
    red: Number.parseFloat(rgb[1]),
    green: Number.parseFloat(rgb[2]),
    blue: Number.parseFloat(rgb[3]),
  };
}

function channel(value: number): number {
  return Math.round(Math.min(255, Math.max(0, value)));
}

function toHex({ red, green, blue }: RgbColor): string {
  return `#${[red, green, blue].map((value) => channel(value).toString(16).padStart(2, "0")).join("")}`
    .toUpperCase();
}

/**
 * Rounds to the 8-bit values the stop will actually be emitted as. Searching on
 * unrounded channels lands just under the floor once the result is quantized.
 */
function mix(from: RgbColor, to: RgbColor, amount: number): RgbColor {
  return {
    red: channel(from.red + (to.red - from.red) * amount),
    green: channel(from.green + (to.green - from.green) * amount),
    blue: channel(from.blue + (to.blue - from.blue) * amount),
  };
}

function relativeLuminance({ red, green, blue }: RgbColor): number {
  const [r, g, b] = [red, green, blue].map((value) => {
    const channel = value / 255;
    return channel <= 0.04045 ? channel / 12.92 : ((channel + 0.055) / 1.055) ** 2.4;
  });
  return r * 0.2126 + g * 0.7152 + b * 0.0722;
}

function contrastRatio(first: RgbColor, second: RgbColor): number {
  const a = relativeLuminance(first);
  const b = relativeLuminance(second);
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}

/**
 * Nudges one gradient stop away from the text that will sit on top of it.
 *
 * Palette roles are generated to contrast with `background`, not with each
 * other, so `primary` frequently lands on or near `foreground` -- the stock
 * dark palette has them identical. Left alone, text over the gradient
 * disappears wherever that stop dominates. Each failing stop is mixed toward
 * whichever of black or white reaches the target first, which preserves as much
 * of the authored hue as the contrast floor allows.
 */
function contrastingStop(
  color: string,
  textColor: RgbColor,
  background?: RgbColor,
): string {
  const parsed = parseColor(color);
  if (!parsed) return color;
  if (contrastRatio(textColor, parsed) >= GRADIENT_BACKGROUND_MINIMUM_CONTRAST) {
    return toHex(parsed);
  }

  // The palette's own background is the preferred direction: text is already
  // guaranteed to read against it, and moving that way is self-correcting per
  // scheme -- a light palette's saturated blue rises toward near-white, a dark
  // palette's bright accent sinks toward near-black and keeps its glow. Black
  // and white are fallbacks for palettes whose background cannot reach the floor.
  const candidates: RgbColor[] = [
    ...(background ? [background] : []),
    { red: 0, green: 0, blue: 0 },
    { red: 255, green: 255, blue: 255 },
  ];
  const target = candidates.find(
    (candidate) =>
      contrastRatio(textColor, candidate) >= GRADIENT_BACKGROUND_MINIMUM_CONTRAST,
  );
  if (!target) return toHex(parsed);

  let low = 0;
  let high = 1;
  for (let iteration = 0; iteration < 20; iteration += 1) {
    const middle = (low + high) / 2;
    if (
      contrastRatio(textColor, mix(parsed, target, middle))
      >= GRADIENT_BACKGROUND_MINIMUM_CONTRAST
    ) {
      high = middle;
    } else {
      low = middle;
    }
  }
  return toHex(mix(parsed, target, high));
}

/**
 * Rewrites the stops that would swallow text drawn in `textColor`. Pure, so the
 * inherited-palette path and the opt-in `contentColor` prop share one behavior.
 */
export function applyGradientBackgroundContentContrast(
  colors: readonly string[],
  textColor: string,
  background?: string,
): string[] {
  const parsed = parseColor(textColor);
  if (!parsed) return [...colors];
  const toward = background ? parseColor(background) : undefined;
  return colors.map((color) => contrastingStop(color, parsed, toward));
}

/**
 * In `duotone` and `ink` modes the effect's own two colors are what content
 * actually sits on -- the ramp underneath is either replaced outright or hidden
 * behind glyphs -- so the same repair that protects the gradient stops has to
 * reach them too, or a palette-driven ASCII background can render pale glyphs
 * on pale paper.
 */
export function applyGradientBackgroundEffectContrast(
  ink: string,
  paper: string,
  textColor: string,
  background?: string,
): { ink: string; paper: string } {
  const [repairedInk, repairedPaper] = applyGradientBackgroundContentContrast(
    [ink, paper],
    textColor,
    background,
  );
  return { ink: repairedInk, paper: repairedPaper };
}

/**
 * The text color the gradient's own box inherits. Content usually sits in a
 * sibling layer under the same ancestor, so this is the closest the background
 * can get to "what will be drawn on me" without inspecting the consumer's tree.
 * `contentColor` exists for the cases where that guess is wrong.
 */
export function resolveGradientBackgroundContentColor(
  element: Element,
): string | undefined {
  return getComputedStyle(element).color.trim() || undefined;
}

interface PaletteRoles {
  colors: string[];
  textColor?: string;
  background?: string;
}

function readPaletteRoles(element: Element): PaletteRoles {
  const styles = getComputedStyle(element);
  const read = (role: string): string | undefined =>
    styles.getPropertyValue(role).trim() || undefined;
  return {
    colors: paletteRoles.map(read).filter((value): value is string => Boolean(value)),
    textColor: paletteTextRoles.map(read).find(Boolean),
    background: read(paletteBackgroundRole),
  };
}

/** Whether this element sits inside a Balsa palette, so colors can be inherited. */
export function hasGradientBackgroundPalette(element: Element): boolean {
  return readPaletteRoles(element).colors.length >= 2;
}

/** The inherited palette background, the preferred direction for stop repair. */
export function resolveGradientBackgroundPaletteBackground(
  element: Element,
): string | undefined {
  return readPaletteRoles(element).background;
}

/** Opacity used when `scrim` is enabled without a value of its own. */
export const GRADIENT_BACKGROUND_SCRIM_OPACITY = 0.65;

export function resolveGradientBackgroundPaletteColors(
  element: Element,
  fallback: readonly string[],
): string[] {
  const { colors, textColor, background } = readPaletteRoles(element);
  if (colors.length < 2) return [...fallback];
  return textColor
    ? applyGradientBackgroundContentContrast(colors, textColor, background)
    : colors;
}

export function buildGradientBackgroundFallback(
  colors: readonly string[],
  direction: number,
): string {
  const stops = colors
    .slice(0, 6)
    .map((color, index, values) =>
      `${color} ${Math.round((index / Math.max(1, values.length - 1)) * 100)}%`,
    )
    .join(", ");
  return `linear-gradient(${direction + 90}deg, ${stops})`;
}

export const gradientBackgroundPresets = Object.freeze(
  Object.fromEntries(
    gradientBackgroundPresetNames.map((name) => [
      name,
      getGradientBackgroundPreset(name),
    ]),
  ) as Record<GradientBackgroundPresetName, BalsaBackgroundConfig>,
);

import {
  Color,
  LinearFilter,
  Mesh,
  NearestFilter,
  NoColorSpace,
  OrthographicCamera,
  PlaneGeometry,
  Scene,
  ShaderMaterial,
  Vector2,
  WebGLRenderer,
  WebGLRenderTarget,
  type IUniform,
  type Texture,
} from "three";
import type {
  BalsaBackgroundConfig,
  GradientBackgroundCaptureOptions,
  GradientBackgroundEffect,
  GradientBackgroundPattern,
  GradientBackgroundQuality,
} from "./gradient-background";
import {
  GRADIENT_BACKGROUND_EFFECT_COLOR_MODES,
  GRADIENT_BACKGROUND_EFFECT_SHAPES,
} from "./gradient-background";
import {
  buildGradientBackgroundFragmentShader,
  gradientBackgroundVertexShader,
} from "./gradient-background-shader";
import {
  buildGradientBackgroundEffectFragmentShader,
  gradientBackgroundEffectVertexShader,
  type GradientBackgroundAppliedEffect,
} from "./gradient-background-effects-shader";
import {
  GRADIENT_BACKGROUND_GLYPH_ASPECT,
  type GradientBackgroundGlyphAtlas,
} from "./gradient-background-glyphs";

interface GradientUniforms extends Record<string, IUniform> {
  uResolution: IUniform<Vector2>;
  uTime: IUniform<number>;
  uSeed: IUniform<number>;
  uScale: IUniform<number>;
  uWarp: IUniform<number>;
  uWave: IUniform<number>;
  uSoftness: IUniform<number>;
  uGrain: IUniform<number>;
  uGrainPixels: IUniform<number>;
  uSourceGrain: IUniform<number>;
  uContrast: IUniform<number>;
  uBrightness: IUniform<number>;
  uDirection: IUniform<number>;
  uFieldFrequency: IUniform<number>;
  uNoiseFrequency: IUniform<number>;
  uNoiseAmount: IUniform<number>;
  uWarpFrequency: IUniform<number>;
  uPatternDensity: IUniform<number>;
  uPatternCenter: IUniform<Vector2>;
  uPatternComplexity: IUniform<number>;
  uFieldOctaves: IUniform<number>;
  uNoiseOctaves: IUniform<number>;
  uColorCount: IUniform<number>;
  uColors: IUniform<Color[]>;
}

interface EffectUniforms extends Record<string, IUniform> {
  uSource: IUniform<Texture | null>;
  uResolution: IUniform<Vector2>;
  uCellPixels: IUniform<number>;
  uEffectAngle: IUniform<number>;
  uEffectMix: IUniform<number>;
  uEffectInvert: IUniform<number>;
  uEffectColorMode: IUniform<number>;
  uEffectShape: IUniform<number>;
  uEffectLevels: IUniform<number>;
  uInk: IUniform<Color>;
  uPaper: IUniform<Color>;
  uSeed: IUniform<number>;
  uGrain: IUniform<number>;
  uGrainPixels: IUniform<number>;
  uGlyphs: IUniform<Texture | null>;
  uGlyphColumns: IUniform<number>;
  uGlyphAspect: IUniform<number>;
  uGlyphAvailable: IUniform<number>;
}

export interface GradientBackgroundQualityProfile {
  pixelRatioScale: number;
  maxPixelRatio: number;
  framesPerSecond: number;
}

const qualityProfiles: Record<Exclude<GradientBackgroundQuality, "auto">, GradientBackgroundQualityProfile> = {
  low: { pixelRatioScale: 0.62, maxPixelRatio: 1, framesPerSecond: 24 },
  medium: { pixelRatioScale: 0.82, maxPixelRatio: 1.25, framesPerSecond: 30 },
  high: { pixelRatioScale: 1, maxPixelRatio: 1.5, framesPerSecond: 30 },
};

/**
 * A smooth gradient survives being rendered below its display size; a lattice
 * of glyphs or dots does not -- the marks land between pixels and turn to mush.
 * Effects therefore hold a higher floor on resolution and pay for it in frame
 * rate, which is already capped low.
 */
const effectPixelRatioFloor = 0.85;

const shaderSeedModulus = 65521;

export function normalizeGradientBackgroundShaderSeed(seed: number): number {
  const integer = Number.isFinite(seed) ? Math.trunc(seed) : 0;
  return ((integer % shaderSeedModulus) + shaderSeedModulus)
    % shaderSeedModulus;
}

export function resolveGradientBackgroundQuality(
  quality: GradientBackgroundQuality,
  width: number,
  hasEffect = false,
): GradientBackgroundQualityProfile {
  const profile = quality === "auto"
    ? (width <= 480 ? qualityProfiles.low : qualityProfiles.medium)
    : qualityProfiles[quality];
  if (!hasEffect || profile.pixelRatioScale >= effectPixelRatioFloor) return profile;
  return { ...profile, pixelRatioScale: effectPixelRatioFloor };
}

/**
 * Cells are authored in CSS pixels so a background looks the same on any
 * display, and so a PNG exported at 1920px shows the density the preview did
 * rather than the density its own pixel count implies.
 */
export function resolveGradientBackgroundCellPixels(
  effectScale: number,
  bufferWidth: number,
  layoutWidth: number,
): number {
  return Math.max(1, effectScale * (bufferWidth / Math.max(1, layoutWidth)));
}

function blobFromCanvas(canvas: HTMLCanvasElement): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => {
      if (blob) resolve(blob);
      else reject(new Error("The browser could not encode the background PNG."));
    }, "image/png");
  });
}

function createRenderTarget(width: number, height: number, effect: GradientBackgroundEffect): WebGLRenderTarget {
  // Cell effects read one texel at a cell center; smoothing that read blurs
  // neighbouring cells into each other. Effects that sample per fragment want
  // the smoothing.
  const filter = effect === "ascii" || effect === "dots" || effect === "halftone"
    ? NearestFilter
    : LinearFilter;
  const target = new WebGLRenderTarget(Math.max(1, width), Math.max(1, height), {
    depthBuffer: false,
    stencilBuffer: false,
    generateMipmaps: false,
    minFilter: filter,
    magFilter: filter,
  });
  // Neither pass is color-managed, so the round trip has to stay a plain copy.
  target.texture.colorSpace = NoColorSpace;
  return target;
}

export class GradientBackgroundRenderer {
  readonly uniforms: GradientUniforms;
  readonly effectUniforms: EffectUniforms;

  private readonly renderer: WebGLRenderer;
  private readonly scene = new Scene();
  private readonly camera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
  private readonly geometry = new PlaneGeometry(2, 2);
  private readonly materials = new Map<GradientBackgroundPattern, ShaderMaterial>();
  private readonly effectMaterials = new Map<GradientBackgroundAppliedEffect, ShaderMaterial>();
  private readonly mesh: Mesh;
  private readonly effectScene = new Scene();
  private effectMesh: Mesh | undefined;
  private target: WebGLRenderTarget | undefined;
  private config: BalsaBackgroundConfig;
  private width = 1;
  private height = 1;
  private disposed = false;
  private profile: GradientBackgroundQualityProfile;

  constructor(
    canvas: HTMLCanvasElement,
    config: BalsaBackgroundConfig,
    colors: readonly string[],
    glyphs?: GradientBackgroundGlyphAtlas,
    /**
     * `preserveDrawingBuffer` is off for the live canvas, where the buffer is
     * composited every frame and keeping it costs memory for nothing. Callers
     * that read pixels back outside the render call -- a thumbnail sheet
     * reading `toDataURL` -- need it on.
     */
    options: { preserveDrawingBuffer?: boolean } = {},
  ) {
    this.config = config;
    this.profile = resolveGradientBackgroundQuality(
      config.quality,
      1,
      config.effect !== "none",
    );
    this.uniforms = {
      uResolution: { value: new Vector2(1, 1) },
      uTime: { value: 0 },
      uSeed: { value: normalizeGradientBackgroundShaderSeed(config.seed) },
      uScale: { value: config.scale },
      uWarp: { value: config.warp },
      uWave: { value: config.wave },
      uSoftness: { value: config.softness },
      uGrain: { value: config.grain },
      uGrainPixels: { value: config.grainSize },
      uSourceGrain: { value: config.effect === "none" ? 1 : 0 },
      uContrast: { value: config.contrast },
      uBrightness: { value: config.brightness },
      uDirection: { value: config.direction },
      uFieldFrequency: { value: config.fieldFrequency },
      uNoiseFrequency: { value: config.noiseFrequency },
      uNoiseAmount: { value: config.noiseAmount },
      uWarpFrequency: { value: config.warpFrequency },
      uPatternDensity: { value: config.patternDensity },
      uPatternCenter: { value: new Vector2(config.patternCenterX, config.patternCenterY) },
      uPatternComplexity: { value: config.patternComplexity },
      uFieldOctaves: { value: config.fieldOctaves },
      uNoiseOctaves: { value: config.noiseOctaves },
      uColorCount: { value: colors.length },
      uColors: { value: Array.from({ length: 6 }, () => new Color("#000000")) },
    };
    this.effectUniforms = {
      uSource: { value: null },
      uResolution: { value: new Vector2(1, 1) },
      uCellPixels: { value: config.effectScale },
      uEffectAngle: { value: config.effectAngle },
      uEffectMix: { value: config.effectMix },
      uEffectInvert: { value: config.effectInvert ? 1 : 0 },
      uEffectColorMode: { value: 0 },
      uEffectShape: { value: 0 },
      uEffectLevels: { value: config.effectLevels },
      uInk: { value: new Color(config.effectInk) },
      uPaper: { value: new Color(config.effectPaper) },
      uSeed: { value: normalizeGradientBackgroundShaderSeed(config.seed) },
      uGrain: { value: config.grain },
      uGrainPixels: { value: config.grainSize },
      uGlyphs: { value: glyphs?.texture ?? null },
      uGlyphColumns: { value: glyphs?.columns ?? 1 },
      uGlyphAspect: { value: glyphs?.aspect ?? GRADIENT_BACKGROUND_GLYPH_ASPECT },
      uGlyphAvailable: { value: glyphs ? 1 : 0 },
    };
    this.mesh = new Mesh(this.geometry, this.patternMaterial(config.pattern));
    this.scene.add(this.mesh);
    this.renderer = new WebGLRenderer({
      canvas,
      alpha: false,
      antialias: false,
      powerPreference: "low-power",
      preserveDrawingBuffer: options.preserveDrawingBuffer ?? false,
    });
    this.renderer.setClearAlpha(1);
    this.update(config, colors, glyphs);
  }

  get framesPerSecond(): number {
    return this.profile.framesPerSecond;
  }

  update(
    config: BalsaBackgroundConfig,
    colors: readonly string[],
    glyphs?: GradientBackgroundGlyphAtlas,
  ): void {
    if (this.disposed) return;
    const previousEffect = this.config.effect;
    this.config = config;
    this.profile = resolveGradientBackgroundQuality(
      config.quality,
      this.width,
      config.effect !== "none",
    );
    this.uniforms.uSeed.value = normalizeGradientBackgroundShaderSeed(
      config.seed,
    );
    this.uniforms.uScale.value = config.scale;
    this.uniforms.uWarp.value = config.warp;
    this.uniforms.uWave.value = config.wave;
    this.uniforms.uSoftness.value = config.softness;
    this.uniforms.uGrain.value = config.grain;
    this.uniforms.uSourceGrain.value = config.effect === "none" ? 1 : 0;
    this.uniforms.uContrast.value = config.contrast;
    this.uniforms.uBrightness.value = config.brightness;
    this.uniforms.uDirection.value = config.direction;
    this.uniforms.uFieldFrequency.value = config.fieldFrequency;
    this.uniforms.uNoiseFrequency.value = config.noiseFrequency;
    this.uniforms.uNoiseAmount.value = config.noiseAmount;
    this.uniforms.uWarpFrequency.value = config.warpFrequency;
    this.uniforms.uPatternDensity.value = config.patternDensity;
    this.uniforms.uPatternCenter.value.set(
      config.patternCenterX,
      config.patternCenterY,
    );
    this.uniforms.uPatternComplexity.value = config.patternComplexity;
    this.uniforms.uFieldOctaves.value = config.fieldOctaves;
    this.uniforms.uNoiseOctaves.value = config.noiseOctaves;
    this.uniforms.uColorCount.value = Math.max(2, Math.min(6, colors.length));
    for (let index = 0; index < 6; index += 1) {
      this.uniforms.uColors.value[index].setStyle(
        colors[Math.min(index, colors.length - 1)] ?? "#000000",
      );
    }
    this.mesh.material = this.patternMaterial(config.pattern);

    this.effectUniforms.uEffectAngle.value = config.effectAngle;
    this.effectUniforms.uEffectMix.value = config.effectMix;
    this.effectUniforms.uEffectInvert.value = config.effectInvert ? 1 : 0;
    this.effectUniforms.uEffectColorMode.value =
      GRADIENT_BACKGROUND_EFFECT_COLOR_MODES.indexOf(config.effectColorMode);
    this.effectUniforms.uEffectShape.value =
      GRADIENT_BACKGROUND_EFFECT_SHAPES.indexOf(config.effectShape);
    this.effectUniforms.uEffectLevels.value = config.effectLevels;
    this.effectUniforms.uInk.value.setStyle(config.effectInk);
    this.effectUniforms.uPaper.value.setStyle(config.effectPaper);
    this.effectUniforms.uSeed.value = normalizeGradientBackgroundShaderSeed(
      config.seed,
    );
    this.effectUniforms.uGrain.value = config.grain;
    this.effectUniforms.uGlyphs.value = glyphs?.texture ?? null;
    this.effectUniforms.uGlyphColumns.value = glyphs?.columns ?? 1;
    this.effectUniforms.uGlyphAspect.value = glyphs?.aspect
      ?? GRADIENT_BACKGROUND_GLYPH_ASPECT;
    this.effectUniforms.uGlyphAvailable.value = glyphs ? 1 : 0;

    const effect = config.effect;
    if (effect === "none") {
      this.releaseTarget();
    } else {
      // The target's filtering depends on the effect, so a change of effect
      // needs a fresh one rather than a resize.
      if (previousEffect !== effect) this.releaseTarget();
      this.effectMesh = this.ensureEffectMesh(effect);
    }
    this.applySize();
  }

  resize(width: number, height: number): void {
    if (this.disposed) return;
    this.width = Math.max(1, Math.round(width));
    this.height = Math.max(1, Math.round(height));
    this.profile = resolveGradientBackgroundQuality(
      this.config.quality,
      this.width,
      this.config.effect !== "none",
    );
    this.applySize();
  }

  render(time: number): void {
    if (this.disposed) return;
    this.uniforms.uTime.value = time;
    if (this.config.effect === "none" || !this.effectMesh) {
      this.renderer.render(this.scene, this.camera);
      return;
    }
    const target = this.ensureTarget();
    this.renderer.setRenderTarget(target);
    this.renderer.render(this.scene, this.camera);
    this.renderer.setRenderTarget(null);
    this.effectUniforms.uSource.value = target.texture;
    this.renderer.render(this.effectScene, this.camera);
  }

  async capturePng(options: GradientBackgroundCaptureOptions = {}): Promise<Blob> {
    if (this.disposed) throw new Error("The background renderer is no longer available.");
    const width = Math.min(4096, Math.max(320, Math.round(options.width ?? this.width)));
    const height = Math.min(4096, Math.max(320, Math.round(options.height ?? this.height)));
    const canvas = document.createElement("canvas");
    const captureRenderer = new WebGLRenderer({
      canvas,
      alpha: false,
      antialias: false,
      powerPreference: "low-power",
      preserveDrawingBuffer: true,
    });
    const previousWidth = this.uniforms.uResolution.value.x;
    const previousHeight = this.uniforms.uResolution.value.y;
    const previousCellPixels = this.effectUniforms.uCellPixels.value;
    const previousGrainPixels = this.uniforms.uGrainPixels.value;
    const previousSource = this.effectUniforms.uSource.value;
    const previousEffectWidth = this.effectUniforms.uResolution.value.x;
    const previousEffectHeight = this.effectUniforms.uResolution.value.y;
    // Render targets carry per-context state, so the capture renderer cannot
    // borrow the live one.
    let captureTarget: WebGLRenderTarget | undefined;
    try {
      captureRenderer.setPixelRatio(1);
      captureRenderer.setSize(width, height, false);
      this.uniforms.uResolution.value.set(width, height);
      // Grain scales with the capture the same way cells do, so an export
      // carries the grain the preview showed rather than a finer one.
      const captureGrainPixels = resolveGradientBackgroundCellPixels(
        this.config.grainSize,
        width,
        this.width,
      );
      this.uniforms.uGrainPixels.value = captureGrainPixels;
      this.effectUniforms.uGrainPixels.value = captureGrainPixels;
      if (this.config.effect === "none" || !this.effectMesh) {
        captureRenderer.render(this.scene, this.camera);
      } else {
        captureTarget = createRenderTarget(width, height, this.config.effect);
        this.effectUniforms.uResolution.value.set(width, height);
        this.effectUniforms.uCellPixels.value = resolveGradientBackgroundCellPixels(
          this.config.effectScale,
          width,
          this.width,
        );
        captureRenderer.setRenderTarget(captureTarget);
        captureRenderer.render(this.scene, this.camera);
        captureRenderer.setRenderTarget(null);
        this.effectUniforms.uSource.value = captureTarget.texture;
        captureRenderer.render(this.effectScene, this.camera);
      }
      return await blobFromCanvas(canvas);
    } finally {
      this.uniforms.uResolution.value.set(previousWidth, previousHeight);
      this.effectUniforms.uResolution.value.set(
        previousEffectWidth,
        previousEffectHeight,
      );
      this.effectUniforms.uCellPixels.value = previousCellPixels;
      this.uniforms.uGrainPixels.value = previousGrainPixels;
      this.effectUniforms.uGrainPixels.value = previousGrainPixels;
      this.effectUniforms.uSource.value = previousSource;
      captureTarget?.dispose();
      captureRenderer.dispose();
      captureRenderer.forceContextLoss();
    }
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.scene.remove(this.mesh);
    if (this.effectMesh) this.effectScene.remove(this.effectMesh);
    this.releaseTarget();
    this.geometry.dispose();
    for (const material of this.materials.values()) material.dispose();
    for (const material of this.effectMaterials.values()) material.dispose();
    this.materials.clear();
    this.effectMaterials.clear();
    this.renderer.renderLists.dispose();
    this.renderer.dispose();
    this.renderer.forceContextLoss();
  }

  /**
   * One compiled program per pattern the user has visited. They share a single
   * uniforms object, so switching pattern swaps the material and nothing else.
   */
  private patternMaterial(pattern: GradientBackgroundPattern): ShaderMaterial {
    const existing = this.materials.get(pattern);
    if (existing) return existing;
    const material = new ShaderMaterial({
      uniforms: this.uniforms,
      vertexShader: gradientBackgroundVertexShader,
      fragmentShader: buildGradientBackgroundFragmentShader(pattern),
      depthTest: false,
      depthWrite: false,
    });
    this.materials.set(pattern, material);
    return material;
  }

  private ensureEffectMesh(effect: GradientBackgroundAppliedEffect): Mesh {
    let material = this.effectMaterials.get(effect);
    if (!material) {
      material = new ShaderMaterial({
        uniforms: this.effectUniforms,
        vertexShader: gradientBackgroundEffectVertexShader,
        fragmentShader: buildGradientBackgroundEffectFragmentShader(effect),
        depthTest: false,
        depthWrite: false,
      });
      this.effectMaterials.set(effect, material);
    }
    if (!this.effectMesh) {
      this.effectMesh = new Mesh(this.geometry, material);
      this.effectScene.add(this.effectMesh);
    } else {
      this.effectMesh.material = material;
    }
    return this.effectMesh;
  }

  private ensureTarget(): WebGLRenderTarget {
    const width = Math.max(1, Math.round(this.width * this.pixelRatio()));
    const height = Math.max(1, Math.round(this.height * this.pixelRatio()));
    if (!this.target) {
      this.target = createRenderTarget(width, height, this.config.effect);
    } else if (this.target.width !== width || this.target.height !== height) {
      this.target.setSize(width, height);
    }
    return this.target;
  }

  private releaseTarget(): void {
    this.target?.dispose();
    this.target = undefined;
  }

  private pixelRatio(): number {
    const devicePixelRatio = typeof window === "undefined"
      ? 1
      : window.devicePixelRatio || 1;
    return Math.min(devicePixelRatio, this.profile.maxPixelRatio)
      * this.profile.pixelRatioScale;
  }

  private applySize(): void {
    const pixelRatio = this.pixelRatio();
    this.renderer.setPixelRatio(pixelRatio);
    this.renderer.setSize(this.width, this.height, false);
    this.uniforms.uResolution.value.set(this.width, this.height);

    const bufferWidth = Math.max(1, Math.round(this.width * pixelRatio));
    const bufferHeight = Math.max(1, Math.round(this.height * pixelRatio));
    this.effectUniforms.uResolution.value.set(bufferWidth, bufferHeight);
    this.effectUniforms.uCellPixels.value = resolveGradientBackgroundCellPixels(
      this.config.effectScale,
      bufferWidth,
      this.width,
    );
    // Grain is authored in CSS pixels for the same reason cells are: otherwise
    // a 2x display halves its size and it fades to almost nothing.
    const grainPixels = resolveGradientBackgroundCellPixels(
      this.config.grainSize,
      bufferWidth,
      this.width,
    );
    this.uniforms.uGrainPixels.value = grainPixels;
    this.effectUniforms.uGrainPixels.value = grainPixels;
    if (this.target) this.target.setSize(bufferWidth, bufferHeight);
  }
}

import type { GradientBackgroundPattern } from "./gradient-background";

export const gradientBackgroundVertexShader = /* glsl */ `
  varying vec2 vUv;

  void main() {
    vUv = uv;
    gl_Position = vec4(position, 1.0);
  }
`;

const shaderPreamble = /* glsl */ `
  precision highp float;

  varying vec2 vUv;
  uniform vec2 uResolution;
  uniform float uTime;
  uniform float uSeed;
  uniform float uScale;
  uniform float uWarp;
  uniform float uWave;
  uniform float uSoftness;
  uniform float uGrain;
  /**
   * Grain cell size already scaled from CSS pixels into drawing-buffer pixels.
   * Authoring it in device pixels made grain half as coarse on a 2x display as
   * on a 1x one, which is both inconsistent and why it reads as barely there
   * on a high-density screen.
   */
  uniform float uGrainPixels;
  /**
   * 1 while this pass draws to the screen, 0 while it draws into a render
   * target an effect will read. Grain has to land in the last pass to survive
   * at full pixel resolution, and applying it in both would double it.
   */
  uniform float uSourceGrain;
  uniform float uContrast;
  uniform float uBrightness;
  uniform float uDirection;
  uniform float uFieldFrequency;
  uniform float uNoiseFrequency;
  uniform float uNoiseAmount;
  uniform float uWarpFrequency;
  uniform float uPatternDensity;
  uniform vec2 uPatternCenter;
  uniform int uPatternComplexity;
  uniform int uFieldOctaves;
  uniform int uNoiseOctaves;
  uniform int uColorCount;
  uniform vec3 uColors[6];

  const float TAU = 6.2831853;
`;

/**
 * Shared by every pattern. `hash21` folds `uSeed` in, so each generator's
 * placement decisions -- blob anchors, cell points -- reseed with the rest of
 * the background rather than needing a seed path of their own.
 */
const noiseLibrary = /* glsl */ `
  float hash21(vec2 p) {
    p = fract(p * vec2(123.34, 456.21));
    p += dot(p, p + 45.32 + uSeed * 0.00017);
    return fract(p.x * p.y);
  }

  /**
   * Grain gets its own hash. The field's one ends on fract(p.x * p.y), whose
   * output falls along hyperbolae -- invisible after being smoothed into fBM,
   * but plainly structured when read per pixel, and worse the further
   * gl_FragCoord gets from the origin. At screen scale that reads as a tiled
   * noise image laid over the art rather than as grain.
   */
  float grainHash(vec2 p) {
    vec3 q = fract(vec3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
  }

  float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(
      mix(hash21(i), hash21(i + vec2(1.0, 0.0)), u.x),
      mix(hash21(i + vec2(0.0, 1.0)), hash21(i + vec2(1.0)), u.x),
      u.y
    ) * 2.0 - 1.0;
  }

  float fieldFbm(vec2 p) {
    float total = 0.0;
    float amplitude = 0.54;
    mat2 rotation = mat2(0.80, -0.60, 0.60, 0.80);
    for (int octave = 0; octave < 4; octave++) {
      if (octave >= uFieldOctaves) break;
      total += amplitude * noise(p);
      p = rotation * p * 2.03 + vec2(13.1, 7.7);
      amplitude *= 0.51;
    }
    return total;
  }

  float surfaceNoiseFbm(vec2 p) {
    float total = 0.0;
    float amplitude = 0.54;
    mat2 rotation = mat2(0.80, -0.60, 0.60, 0.80);
    for (int octave = 0; octave < 6; octave++) {
      if (octave >= uNoiseOctaves) break;
      total += amplitude * noise(p);
      p = rotation * p * 2.03 + vec2(7.1, 11.7);
      amplitude *= 0.51;
    }
    return total;
  }

  vec3 colorRamp(float value) {
    float scaled = clamp(value, 0.0, 0.9999) * float(max(uColorCount - 1, 1));
    int index = int(floor(scaled));
    float amount = smoothstep(0.0, 1.0, fract(scaled));
    vec3 left = uColors[0];
    vec3 right = uColors[1];
    if (index == 1) { left = uColors[1]; right = uColors[2]; }
    if (index == 2) { left = uColors[2]; right = uColors[3]; }
    if (index == 3) { left = uColors[3]; right = uColors[4]; }
    if (index >= 4) { left = uColors[4]; right = uColors[5]; }
    return mix(left, right, amount);
  }

  /** Sharp crest from a repeating phase; \`uSoftness\` sets how tight the crest is. */
  float ridgeShape(float phase) {
    float ridge = 1.0 - abs(sin(phase));
    return pow(clamp(ridge, 0.0, 1.0), mix(4.8, 1.25, uSoftness));
  }

  /**
   * The shared tail every generator ends on: soft patterns keep their raw
   * range, crisp ones get pushed toward the ramp's ends.
   */
  float shapeField(float field) {
    return mix(smoothstep(-0.05, 1.05, field), field, uSoftness * 0.45);
  }

  vec2 patternCenter() {
    return uPatternCenter * uScale;
  }
`;

/**
 * Each generator turns the shared warped domain into one scalar. They all
 * receive the same inputs so warp, scale, direction and the octave counts keep
 * working identically across patterns.
 */
const patternBodies: Record<GradientBackgroundPattern, string> = {
  /**
   * The original wave field, unchanged. Anything that alters its output changes
   * how every pre-existing preset and saved background renders.
   */
  ribbon: /* glsl */ `
    float patternField(vec2 p, vec2 warped, vec2 q, vec2 r, float terrain, float phase) {
      float ridgePhase = warped.y * uPatternDensity
        + r.x * 2.8
        + terrain * 1.55
        + sin(warped.x * 1.4 + q.y * 2.0) * 0.36;
      float ridge = ridgeShape(ridgePhase);

      float broad = terrain * 0.34 + r.y * 0.24 + q.x * 0.13;
      float field = 0.5 + broad + (ridge - 0.28) * uWave * 0.34;
      return shapeField(field);
    }
  `,
  /**
   * Distance from the center drives the ramp, so `wave` at zero leaves a clean
   * bloom and raising it rings the bloom with concentric crests.
   */
  radial: /* glsl */ `
    float patternField(vec2 p, vec2 warped, vec2 q, vec2 r, float terrain, float phase) {
      // Not named \`distance\`: that is a GLSL built-in function, and hiding one
      // behind a local is rejected by the ES 3.00 translator three compiles
      // these through.
      float radius = length(warped - patternCenter());
      float ridge = ridgeShape(
        radius * uPatternDensity * 3.14159265 + terrain * 1.2 + r.x * 1.6
      );
      float bloom = 1.0 - smoothstep(0.0, 1.7, radius);
      float broad = terrain * 0.24 + r.y * 0.18 + q.x * 0.1;
      float field = 0.5 + broad + (bloom - 0.35) * 0.46 + (ridge - 0.28) * uWave * 0.3;
      return shapeField(field);
    }
  `,
  /**
   * Angle drives the ramp with a radius-dependent twist, which reads as a
   * chrome sweep rather than a flat pinwheel. The arm count is rounded to an
   * integer because a fractional one leaves a hard seam where atan wraps.
   */
  conic: /* glsl */ `
    float patternField(vec2 p, vec2 warped, vec2 q, vec2 r, float terrain, float phase) {
      vec2 offset = warped - patternCenter();
      float angle = atan(offset.y, offset.x);
      float twist = length(offset) * uWarp * 1.6;
      float arms = max(1.0, floor(uPatternDensity + 0.5));
      float sweep = 0.5 + 0.5 * sin(angle * arms + twist + terrain * 0.9);
      float ridge = ridgeShape(angle * arms + twist * 1.4 + r.x * 1.5);
      float broad = terrain * 0.22 + q.x * 0.12;
      float field = 0.5 + broad + (sweep - 0.5) * 0.55 + (ridge - 0.28) * uWave * 0.26;
      return shapeField(field);
    }
  `,
  /**
   * Overlapping gaussians drifting on slow lissajous paths -- the soft mesh
   * gradient look. Anchors come from the seed, so a background stays the same
   * background across reloads.
   */
  blobs: /* glsl */ `
    float patternField(vec2 p, vec2 warped, vec2 q, vec2 r, float terrain, float phase) {
      vec2 center = patternCenter();
      float accumulated = 0.0;
      for (int index = 0; index < 8; index++) {
        if (index >= uPatternComplexity) break;
        float slot = float(index);
        vec2 anchor = vec2(
          hash21(vec2(slot, 3.7)),
          hash21(vec2(slot, 9.1))
        ) * 2.0 - 1.0;
        vec2 drift = vec2(
          sin(phase * (0.7 + slot * 0.13) + slot),
          cos(phase * (0.55 + slot * 0.17) + slot * 1.7)
        );
        vec2 position = center + (anchor + drift * 0.35) * 1.15;
        float radius = 0.55 + hash21(vec2(slot, 5.3)) * 0.5;
        float reach = length(warped - position) / radius;
        accumulated += exp(-reach * reach * 1.6);
      }
      float merged = accumulated / (0.6 + float(uPatternComplexity) * 0.45);
      float broad = terrain * 0.22 + q.x * 0.12;
      float field = 0.5 + broad + (merged - 0.3) * uWave * 0.95;
      return shapeField(field);
    }
  `,
  /**
   * Topographic banding: the elevation is sliced at even intervals and each
   * slice edge is drawn as a line whose width follows `softness`.
   */
  contour: /* glsl */ `
    float patternField(vec2 p, vec2 warped, vec2 q, vec2 r, float terrain, float phase) {
      float elevation = terrain * 1.35 + r.y * 0.55 + q.x * 0.35;
      float band = abs(fract(elevation * uPatternDensity) - 0.5) * 2.0;
      float line = 1.0 - smoothstep(0.0, mix(0.12, 0.85, uSoftness), band);
      float broad = terrain * 0.3 + r.y * 0.2;
      float field = 0.5 + broad * 0.6 + (line - 0.3) * uWave * 0.5;
      return shapeField(field);
    }
  `,
  /**
   * Worley cells: `second - first` picks out the facet edges, `first` shades
   * the interiors. The two together read as cracked glass over the warped
   * field. The heaviest pattern -- nine hashed cell points per pixel.
   */
  cellular: /* glsl */ `
    vec2 cellPoint(vec2 cell, float phase) {
      vec2 point = vec2(hash21(cell + 0.13), hash21(cell + 7.31));
      return 0.5 + 0.5 * sin(phase * 0.9 + TAU * point);
    }

    float patternField(vec2 p, vec2 warped, vec2 q, vec2 r, float terrain, float phase) {
      vec2 position = (warped - patternCenter()) * (1.0 + float(uPatternComplexity) * 0.55);
      vec2 base = floor(position);
      vec2 local = fract(position);
      float first = 8.0;
      float second = 8.0;
      for (int y = -1; y <= 1; y++) {
        for (int x = -1; x <= 1; x++) {
          vec2 offset = vec2(float(x), float(y));
          float reach = length(offset + cellPoint(base + offset, phase) - local);
          if (reach < first) {
            second = first;
            first = reach;
          } else if (reach < second) {
            second = reach;
          }
        }
      }
      float edge = 1.0 - smoothstep(0.0, mix(0.08, 0.6, uSoftness), second - first);
      float broad = terrain * 0.28 + r.y * 0.18;
      float field = 0.5 + broad + (first - 0.45) * 0.5 + (edge - 0.3) * uWave * 0.45;
      return shapeField(field);
    }
  `,
};

/**
 * Everything outside the pattern stage: the domain warp that feeds it, then the
 * color ramp, surface noise, grain and dither that dress its output.
 */
const shaderMain = /* glsl */ `
  void main() {
    vec2 uv = vUv - 0.5;
    uv.x *= uResolution.x / max(uResolution.y, 1.0);

    float angle = radians(uDirection);
    mat2 flowRotation = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
    vec2 p = flowRotation * uv * uScale;
    float phase = uTime * 0.12;

    vec2 q = vec2(
      fieldFbm(p * uWarpFrequency + vec2(phase, -phase * 0.41)),
      fieldFbm(p * uWarpFrequency + vec2(5.2, 1.3) + vec2(-phase * 0.34, phase * 0.63))
    );
    vec2 warped = p + q * uWarp * 0.72;
    vec2 r = vec2(
      fieldFbm(warped * uFieldFrequency + q * 0.85 + vec2(1.7, 9.2)),
      fieldFbm(warped * uFieldFrequency - q * 0.65 + vec2(8.3, 2.8))
    );

    float terrain = fieldFbm(warped * uFieldFrequency + r * 0.76);
    float field = patternField(p, warped, q, r, terrain, phase);
    field = (field - 0.5) * uContrast + 0.5 + uBrightness;

    vec3 color = colorRamp(field);
    vec2 surfaceNoisePosition = flowRotation * uv * uNoiseFrequency * 6.0;
    surfaceNoisePosition += vec2(uSeed * 0.0013, -uSeed * 0.0009);
    float surfaceNoise = surfaceNoiseFbm(surfaceNoisePosition);
    color += surfaceNoise * uNoiseAmount;

    float grainCell = max(0.35, uGrainPixels);
    vec2 grainCoord = floor(gl_FragCoord.xy / grainCell);
    float grain = grainHash(grainCoord + vec2(uSeed * 0.013, uSeed * 0.029)) - 0.5;
    color += grain * uGrain * uSourceGrain;

    float dither = (grainHash(gl_FragCoord.xy + 17.0) - 0.5) / 255.0;
    color += dither;
    gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
  }
`;

/**
 * One program per pattern rather than one program branching on a uniform: the
 * dead generators never reach the compiler, which keeps register pressure off
 * the low-power GPUs this component targets. Programs are cached by the
 * renderer, so the compile happens once per pattern the user visits.
 */
export function buildGradientBackgroundFragmentShader(
  pattern: GradientBackgroundPattern,
): string {
  return [shaderPreamble, noiseLibrary, patternBodies[pattern], shaderMain].join(
    "\n",
  );
}

import type { GradientBackgroundEffect } from "./gradient-background";

export type GradientBackgroundAppliedEffect = Exclude<
  GradientBackgroundEffect,
  "none"
>;

export const gradientBackgroundEffectVertexShader = /* glsl */ `
  varying vec2 vUv;

  void main() {
    vUv = uv;
    gl_Position = vec4(position, 1.0);
  }
`;

/**
 * Shared by every effect. `uCellPixels` arrives already scaled from CSS pixels
 * into drawing-buffer pixels, which is what keeps a background's mark density
 * identical across device pixel ratios and in a PNG captured at another size.
 */
const effectPreamble = /* glsl */ `
  precision highp float;

  varying vec2 vUv;
  uniform sampler2D uSource;
  uniform vec2 uResolution;
  uniform float uCellPixels;
  uniform float uEffectAngle;
  uniform float uEffectMix;
  uniform float uEffectInvert;
  uniform int uEffectColorMode;
  uniform int uEffectShape;
  uniform int uEffectLevels;
  uniform vec3 uInk;
  uniform vec3 uPaper;
  uniform float uSeed;
  uniform float uGrain;
  /** Grain cell size, already scaled from CSS pixels into buffer pixels. */
  uniform float uGrainPixels;

  const int COLOR_MODE_GRADIENT = 0;
  const int COLOR_MODE_DUOTONE = 1;
  const int COLOR_MODE_INK = 2;

  // Deliberately not named \`luminance\`: three injects its own luminance()
  // helper into every non-raw ShaderMaterial fragment shader, and redefining
  // it fails the whole program to compile. Nothing in here may reuse a name
  // from three's injected prefix.
  float fieldLuminance(vec3 rgb) {
    return dot(rgb, vec3(0.2126, 0.7152, 0.0722));
  }

  /**
   * Hash without sine. Distributes far better than a multiply-and-fract pair
   * ending on fract(x * y), whose output falls along hyperbolae and turns into
   * visible repeating structure once fragment coordinates get large -- which
   * is what makes weak grain read as a tiled overlay instead of film.
   */
  float grainHash(vec2 p) {
    vec3 q = fract(vec3(p.xyx) * 0.1031);
    q += dot(q, q.yzx + 33.33);
    return fract((q.x + q.y) * q.z);
  }

  // Not named \`degrees\`: that is a GLSL built-in function, and hiding one
  // behind a parameter name is rejected by the ES 3.00 translator three
  // compiles these through.
  mat2 rotation(float turn) {
    float angle = radians(turn);
    return mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
  }

  float cellPixels() {
    return max(1.0, uCellPixels);
  }

  /**
   * How much mark this luminance earns. Bright earns more, because these
   * backgrounds are usually light figures on a dark field; effectInvert is
   * for the print-like reading where dark earns more ink.
   */
  float tone(float value) {
    return clamp(mix(value, 1.0 - value, uEffectInvert), 0.0, 1.0);
  }

  /** The gradient color at the center of the cell a fragment belongs to. */
  vec3 cellColor(vec2 cell, vec2 size) {
    vec2 fragment = rotation(-uEffectAngle) * ((cell + 0.5) * size);
    return texture2D(uSource, clamp(fragment / uResolution, vec2(0.0), vec2(1.0))).rgb;
  }

  float shapeDistance(vec2 local) {
    if (uEffectShape == 1) return max(abs(local.x), abs(local.y));
    if (uEffectShape == 2) return min(abs(local.x), abs(local.y));
    return length(local);
  }

  /**
   * Turns a mark's coverage into color. The gradient mode keeps the field's
   * own hue and darkens between marks; duotone replaces it with the ink and
   * paper pair; ink lays the ink over the untouched field.
   */
  vec3 resolveColor(vec3 field, float coverage) {
    if (uEffectColorMode == COLOR_MODE_DUOTONE) return mix(uPaper, uInk, coverage);
    if (uEffectColorMode == COLOR_MODE_INK) return mix(field, uInk, coverage);
    return mix(field * BALSA_MARK_FLOOR, field, coverage);
  }
`;

const effectBodies: Record<GradientBackgroundAppliedEffect, string> = {
  /** Size-modulated dots on a rotatable grid -- the classic print screen. */
  halftone: /* glsl */ `
    vec3 applyEffect(vec3 source) {
      vec2 size = vec2(cellPixels());
      vec2 lattice = rotation(uEffectAngle) * gl_FragCoord.xy / size;
      vec3 field = cellColor(floor(lattice), size);
      vec2 local = fract(lattice) - 0.5;
      float radius = tone(fieldLuminance(field)) * 0.72;
      float edge = 1.5 / size.x;
      float coverage = 1.0 - smoothstep(radius - edge, radius + edge, shapeDistance(local));
      return resolveColor(field, coverage);
    }
  `,
  /** Fixed-size marks whose brightness, not size, follows the field. */
  dots: /* glsl */ `
    vec3 applyEffect(vec3 source) {
      vec2 size = vec2(cellPixels());
      vec2 lattice = rotation(uEffectAngle) * gl_FragCoord.xy / size;
      vec3 field = cellColor(floor(lattice), size);
      vec2 local = fract(lattice) - 0.5;
      float edge = 1.5 / size.x;
      float mark = 1.0 - smoothstep(0.32 - edge, 0.32 + edge, shapeDistance(local));
      return resolveColor(field, mark * tone(fieldLuminance(field)));
    }
  `,
  /**
   * Scanlines displaced and thickened by the field underneath. Sampled per
   * fragment rather than per cell so the lines flow continuously instead of
   * stepping between cells.
   */
  lines: /* glsl */ `
    vec3 applyEffect(vec3 source) {
      float size = cellPixels();
      vec2 rotated = rotation(uEffectAngle) * gl_FragCoord.xy;
      float amount = tone(fieldLuminance(source));
      float local = fract(rotated.y / size) - 0.5;
      float wobble = sin(rotated.x / size * 1.7) * amount * 0.35;
      float thickness = 0.06 + amount * 0.34;
      float edge = 1.5 / size;
      float coverage = 1.0
        - smoothstep(thickness - edge, thickness + edge, abs(local - wobble));
      return resolveColor(source, coverage);
    }
  `,
  /**
   * Ordered dithering. The Bayer threshold is built by recursion rather than a
   * lookup array because GLSL ES 1.0 cannot index a const array dynamically.
   */
  dither: /* glsl */ `
    float bayer2(vec2 position) {
      position = floor(position);
      return fract(position.x / 2.0 + position.y * position.y * 0.75);
    }

    float bayer4(vec2 position) {
      return bayer2(position * 0.5) * 0.25 + bayer2(position);
    }

    float bayer8(vec2 position) {
      return bayer4(position * 0.5) * 0.25 + bayer2(position);
    }

    vec3 applyEffect(vec3 source) {
      // The dither grid is finer than a mark grid at the same setting -- a
      // 10px dither block reads as mush, a 2.5px one reads as texture.
      vec2 position = gl_FragCoord.xy / max(1.0, cellPixels() * 0.25);
      float threshold = bayer8(position);
      float steps = float(max(2, uEffectLevels)) - 1.0;
      if (uEffectColorMode == COLOR_MODE_GRADIENT) {
        return floor(source * steps + threshold) / steps;
      }
      float shade = floor(tone(fieldLuminance(source)) * steps + threshold) / steps;
      return resolveColor(source, clamp(shade, 0.0, 1.0));
    }
  `,
  /** Engraving hatch: each luminance step switches on another line set. */
  crosshatch: /* glsl */ `
    float hatch(float turn, float size, float edge) {
      vec2 rotated = rotation(turn) * gl_FragCoord.xy;
      float local = abs(fract(rotated.y / size) - 0.5);
      return 1.0 - smoothstep(0.09 - edge, 0.09 + edge, local);
    }

    vec3 applyEffect(vec3 source) {
      float size = cellPixels();
      float edge = 1.5 / size;
      float amount = tone(fieldLuminance(source));
      float levels = float(max(2, uEffectLevels));
      float coverage = 0.0;
      for (int index = 0; index < 8; index++) {
        if (index >= uEffectLevels) break;
        float threshold = (float(index) + 1.0) / (levels + 1.0);
        if (amount >= threshold) {
          coverage = max(coverage, hatch(uEffectAngle + float(index) * 37.0, size, edge));
        }
      }
      return resolveColor(source, coverage);
    }
  `,
  /**
   * Glyphs from a runtime-built atlas, one column per character, ordered from
   * lightest to heaviest by measured ink. Cells are taller than wide because
   * monospace glyphs are, so square cells would stretch every character.
   *
   * `uGlyphAvailable` covers the case where the atlas could not be built at all
   * (no document, no 2D context): the effect degrades to a plain dot rather
   * than sampling an empty texture and painting the screen black.
   */
  ascii: /* glsl */ `
    uniform sampler2D uGlyphs;
    uniform float uGlyphColumns;
    uniform float uGlyphAspect;
    uniform float uGlyphAvailable;

    vec3 applyEffect(vec3 source) {
      vec2 size = vec2(cellPixels(), cellPixels() * uGlyphAspect);
      vec2 lattice = rotation(uEffectAngle) * gl_FragCoord.xy / size;
      vec3 field = cellColor(floor(lattice), size);
      vec2 local = fract(lattice);
      float amount = tone(fieldLuminance(field));

      if (uGlyphAvailable < 0.5) {
        float edge = 1.5 / size.x;
        float mark = 1.0 - smoothstep(0.32 - edge, 0.32 + edge, length(local - 0.5));
        return resolveColor(field, mark * amount);
      }

      float column = floor(clamp(amount, 0.0, 0.9999) * uGlyphColumns);
      // The atlas is uploaded unflipped, so the row runs top-down while
      // gl_FragCoord runs bottom-up.
      vec2 atlas = vec2((column + local.x) / uGlyphColumns, 1.0 - local.y);
      float coverage = texture2D(uGlyphs, atlas).r;
      return resolveColor(field, coverage);
    }
  `,
};

/**
 * `uEffectMix` blends against the untouched source, so a mix of zero is an
 * exact passthrough -- which is also the cheapest way to prove the render
 * target round-trip is not shifting color.
 */
const effectMain = /* glsl */ `
  void main() {
    vec3 source = texture2D(uSource, vUv).rgb;
    vec3 color = mix(source, applyEffect(source), clamp(uEffectMix, 0.0, 1.0));

    // Grain belongs to whichever pass runs last. A cell effect reads the field
    // once per cell, so grain applied upstream is sampled at one point and
    // spread flat across the whole cell -- the texture disappears and the
    // result looks plastic. Re-applying it here restores it per pixel.
    float grainCell = max(0.35, uGrainPixels);
    vec2 grainCoord = floor(gl_FragCoord.xy / grainCell);
    float grain = grainHash(grainCoord + vec2(uSeed * 0.013, uSeed * 0.029)) - 0.5;
    color += grain * uGrain;

    color += (grainHash(gl_FragCoord.xy + 17.0) - 0.5) / 255.0;
    gl_FragColor = vec4(clamp(color, 0.0, 1.0), 1.0);
  }
`;

/**
 * How much of the field survives between marks, in the gradient color mode.
 * Glyphs carry their own tone through which character is chosen, so ASCII
 * wants a clean ground -- lifting it turns the effect into a grid of tinted
 * boxes with type sitting on top, which is the field showing through rather
 * than the field being drawn. The mark-based effects do want the wash, since
 * a dot only carries tone through its size.
 */
const markFloors: Record<GradientBackgroundAppliedEffect, string> = {
  ascii: "0.0",
  halftone: "0.18",
  dots: "0.18",
  lines: "0.18",
  dither: "0.18",
  crosshatch: "0.18",
};

export function buildGradientBackgroundEffectFragmentShader(
  effect: GradientBackgroundAppliedEffect,
): string {
  return [
    `#define BALSA_MARK_FLOOR ${markFloors[effect]}`,
    effectPreamble,
    effectBodies[effect],
    effectMain,
  ].join("\n");
}

import { CanvasTexture, ClampToEdgeWrapping, LinearFilter, type Texture } from "three";

/**
 * Fallback cell aspect for when no atlas could be built and the effect falls
 * back to a dot. Real atlases derive their own from the font's metrics.
 */
export const GRADIENT_BACKGROUND_GLYPH_ASPECT = 1.3;

/** Atlas cell width in texels. 48 keeps a 64-character set inside 3072px. */
const GLYPH_CELL_WIDTH = 48;

/** Size the metrics are measured at before being scaled into the cell. */
const GLYPH_PROBE_SIZE = 100;

/**
 * How much of the cell the heaviest glyph's ink fills. Just short of 1 so
 * antialiased edges are not clipped by the cell boundary, which would leave a
 * hard seam between neighbouring glyphs.
 */
const GLYPH_FILL = 0.96;

const GLYPH_FONT_STACK = "ui-monospace, SFMono-Regular, Menlo, Consolas, monospace";

export interface GradientBackgroundGlyphAtlas {
  texture: Texture;
  /** One column per character, in the order the shader indexes them. */
  columns: number;
  /** Cell height over cell width, derived from the drawn glyphs' own ink. */
  aspect: number;
  /** The characters as drawn: the requested set, reordered by ink weight. */
  characters: string;
  dispose: () => void;
}

/**
 * Reading pixels back is the slow part of building an atlas, and the studio's
 * character field rebuilds on every edit, so orderings are remembered. Only the
 * ordering is cached -- textures stay owned by whoever created them, which
 * keeps one component's teardown from blanking another's glyphs.
 */
const orderingCache = new Map<string, string>();

interface GlyphBlock {
  /** Widest ink across the set, at the probe size. */
  width: number;
  ascent: number;
  descent: number;
}

/**
 * The bounding box of the heaviest glyph in the set, which is what gets fitted
 * to the cell. Measuring each glyph and normalizing it individually would blow
 * a period up to the size of an at-sign and destroy the tonal ramp -- one
 * shared box keeps every glyph's weight relative to the others.
 */
function measureGlyphBlock(
  context: CanvasRenderingContext2D,
  characters: readonly string[],
): GlyphBlock {
  context.font = `${GLYPH_PROBE_SIZE}px ${GLYPH_FONT_STACK}`;
  let width = 0;
  let ascent = 0;
  let descent = 0;
  for (const character of characters) {
    const metrics = context.measureText(character);
    // Older engines omit the ink box; the advance width and a nominal cap
    // height keep the atlas usable rather than collapsing it to zero.
    const inkWidth = metrics.actualBoundingBoxLeft === undefined
      ? metrics.width
      : metrics.actualBoundingBoxLeft + metrics.actualBoundingBoxRight;
    width = Math.max(width, inkWidth);
    ascent = Math.max(ascent, metrics.actualBoundingBoxAscent ?? GLYPH_PROBE_SIZE * 0.72);
    descent = Math.max(descent, metrics.actualBoundingBoxDescent ?? GLYPH_PROBE_SIZE * 0.08);
  }
  if (width <= 0) width = GLYPH_PROBE_SIZE * 0.6;
  if (ascent + descent <= 0) ascent = GLYPH_PROBE_SIZE * 0.72;
  return { width, ascent, descent };
}

interface GlyphLayout {
  cellWidth: number;
  cellHeight: number;
  aspect: number;
  fontSize: number;
  baseline: number;
}

/**
 * Scales the shared ink box to fill the cell, and lets the cell's aspect follow
 * from the box rather than being imposed. A fixed aspect leaves the glyphs
 * floating in their cells with the field showing through the gaps, which turns
 * the effect into a grid of tinted boxes instead of a picture made of type.
 */
function layoutGlyphs(block: GlyphBlock): GlyphLayout {
  const cellWidth = GLYPH_CELL_WIDTH;
  const blockHeight = block.ascent + block.descent;
  const scale = (cellWidth * GLYPH_FILL) / block.width;
  const cellHeight = Math.max(1, Math.round((blockHeight * scale) / GLYPH_FILL));
  return {
    cellWidth,
    cellHeight,
    aspect: cellHeight / cellWidth,
    fontSize: GLYPH_PROBE_SIZE * scale,
    baseline: (cellHeight - blockHeight * scale) / 2 + block.ascent * scale,
  };
}

function drawGlyphs(
  context: CanvasRenderingContext2D,
  characters: readonly string[],
  layout: GlyphLayout,
): void {
  context.fillStyle = "#000000";
  context.fillRect(0, 0, layout.cellWidth * characters.length, layout.cellHeight);
  context.fillStyle = "#FFFFFF";
  context.font = `${layout.fontSize}px ${GLYPH_FONT_STACK}`;
  context.textAlign = "center";
  context.textBaseline = "alphabetic";
  characters.forEach((character, index) => {
    context.fillText(
      character,
      (index + 0.5) * layout.cellWidth,
      layout.baseline,
    );
  });
}

/**
 * Sorts by how much ink each glyph actually puts on the cell, so the
 * luminance-to-glyph mapping rises monotonically no matter what order the
 * characters were typed in. Without this a set like "@ .#" produces noise
 * rather than shading.
 */
function orderByInk(
  context: CanvasRenderingContext2D,
  characters: readonly string[],
  layout: GlyphLayout,
): string[] {
  const width = layout.cellWidth * characters.length;
  let pixels: Uint8ClampedArray;
  try {
    pixels = context.getImageData(0, 0, width, layout.cellHeight).data;
  } catch {
    // A tainted or unreadable canvas still renders; it just keeps the
    // author's ordering instead of the measured one.
    return [...characters];
  }

  const coverage = characters.map(() => 0);
  for (let y = 0; y < layout.cellHeight; y += 1) {
    for (let x = 0; x < width; x += 1) {
      coverage[Math.floor(x / layout.cellWidth)] += pixels[(y * width + x) * 4];
    }
  }
  return characters
    .map((character, index) => ({ character, ink: coverage[index] }))
    .sort((first, second) => first.ink - second.ink)
    .map((entry) => entry.character);
}

/**
 * Returns `undefined` where a canvas is unavailable -- server rendering, or a
 * test environment without a 2D context. Callers treat that as "no atlas" and
 * fall back to a dot mark rather than sampling an empty texture.
 */
export function createGradientBackgroundGlyphAtlas(
  characters: string,
): GradientBackgroundGlyphAtlas | undefined {
  if (typeof document === "undefined") return undefined;

  const requested = Array.from(characters);
  if (requested.length < 2) return undefined;

  const canvas = document.createElement("canvas");
  const context = canvas.getContext("2d", { willReadFrequently: true });
  if (!context) return undefined;

  const layout = layoutGlyphs(measureGlyphBlock(context, requested));
  canvas.width = layout.cellWidth * requested.length;
  canvas.height = layout.cellHeight;

  const cacheKey = requested.join("");
  let ordered = orderingCache.get(cacheKey);
  if (!ordered) {
    drawGlyphs(context, requested, layout);
    ordered = orderByInk(context, requested, layout).join("");
    orderingCache.set(cacheKey, ordered);
  }
  drawGlyphs(context, Array.from(ordered), layout);

  const texture = new CanvasTexture(canvas);
  // The shader flips the row itself, because gl_FragCoord counts up from the
  // bottom while the canvas was drawn from the top.
  texture.flipY = false;
  texture.minFilter = LinearFilter;
  texture.magFilter = LinearFilter;
  texture.generateMipmaps = false;
  texture.wrapS = ClampToEdgeWrapping;
  texture.wrapT = ClampToEdgeWrapping;
  texture.needsUpdate = true;

  return {
    texture,
    columns: requested.length,
    aspect: layout.aspect,
    characters: ordered,
    dispose: () => texture.dispose(),
  };
}
